(function(){'use strict';
const KEY='nawaf-hq-v5';
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason:'connection-request'}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
async function persist(s){const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({state:s}),cache:'no-store'});const j=await r.json().catch(()=>({}));if(!r.ok||!j?.ok)throw new Error(j?.error||'STATE_SAVE_FAILED')}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function pending(s){return (s.connectionRequests||[]).filter(x=>['PENDING','APPROVED'].includes(x.status))}
function ensure(){let root=document.getElementById('hq-connection-center');if(root)return root;root=document.createElement('div');root.id='hq-connection-center';root.style.cssText='position:fixed;left:18px;bottom:72px;z-index:10020;width:min(390px,calc(100vw - 36px));font-family:system-ui;direction:rtl';document.body.appendChild(root);return root}
let lastHtml='';
function render(){const s=read(),items=pending(s),root=ensure();const html=!items.length?'':items.slice(0,3).map(r=>`<div style="margin-top:10px;padding:14px;border:1px solid rgba(215,170,75,.35);border-radius:14px;background:#0d141d;box-shadow:0 14px 40px rgba(0,0,0,.4);color:#f5f7fa"><div style="font-weight:800;color:#f0cf82;margin-bottom:5px">طلب ربط من الموظف</div><div style="font-size:13px;font-weight:700">${esc(r.providerName||r.provider)}</div><div style="font-size:12px;color:#aeb8c5;margin:7px 0 10px;line-height:1.7">${esc(r.reason||'تحتاج المهمة هذا الربط لإكمال التنفيذ.')}</div><div style="font-size:11px;color:#7f8c9d;margin-bottom:10px">${(r.permissions||[]).map(x=>'• '+esc(x)).join('<br>')}</div><div style="display:flex;gap:8px;flex-wrap:wrap"><button data-conn-approve="${esc(r.id)}" style="cursor:pointer;border:1px solid rgba(215,170,75,.45);background:#151b23;color:#f0cf82;border-radius:9px;padding:8px 11px;font-weight:700">${r.status==='APPROVED'?'فتح إعداد الربط':'موافقة وربط'}</button><button data-conn-decline="${esc(r.id)}" style="cursor:pointer;border:1px solid #313a45;background:#111820;color:#aeb8c5;border-radius:9px;padding:8px 11px">رفض</button></div>${r.status==='APPROVED'?'<div style="font-size:11px;color:#86d39a;margin-top:8px">تمت الموافقة. بعد إضافة مفاتيح Paper على الخادم ستكمل المهمة تلقائيًا.</div>':''}</div>`).join('');if(html===lastHtml)return;lastHtml=html;root.innerHTML=html}
async function decide(id,approved){const s=read(),r=(s.connectionRequests||[]).find(x=>x.id===id);if(!r)return;r.status=approved?'APPROVED':'DECLINED';r.updatedAt=new Date().toISOString();const task=(s.tasks||[]).find(t=>t.id===r.taskId);if(task&&!approved){task.status='WAITING_FOR_NAWAF';task.blockedReason='تم رفض طلب الربط.';task.blockerType='APPROVAL';task.updatedAt=r.updatedAt;const e=(s.employees||[]).find(x=>x.id===task.employeeId);if(e){e.status='WAITING_FOR_NAWAF';e.updatedAt=r.updatedAt}}write(s);render();try{await persist(s)}catch{}if(approved&&r.setupUrl)window.open(r.setupUrl,'_blank','noopener')}
document.addEventListener('click',e=>{const a=e.target.closest('[data-conn-approve]');if(a){decide(a.dataset.connApprove,true);return}const d=e.target.closest('[data-conn-decline]');if(d)decide(d.dataset.connDecline,false)},true);
window.addEventListener('storage',render);window.addEventListener('nawaf:state-updated',render);
function boot(){render();setInterval(render,3000)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
